const mongoose = require('mongoose');
const jwt = require('jsonwebtoken');

const maxTimeMS = Number(process.env.MAX_TIME_MS) || 1000;

module.exports = {
    authValidation: async function (req, res, next) {
        try {
            const appRecord = await mongoose.connection.collection('apps').findOne({
                maskId: req.url.split('/')[1],
                state: "enabled",
                recStatus: "active"
            }, { maxTimeMS: maxTimeMS });
            if (!appRecord) {
                return res.status(404).json({ success: false, error: 'No app found' });
            }
            if (appRecord.accessType === 'public') {
                return next();
            }

            const authHeader = req.headers['authorization'];
            if (!authHeader) {
                return res.status(401).json({ success: false, error: 'Authorization header is required' });
            }
            if (authHeader.split(' ')[0] !== 'Bearer') {
                return res.status(401).json({ success: false, error: 'Authorization header must start with Bearer' });
            }
            const token = authHeader.split(' ')[1]; //remove Bearer
            if (!token) {
                return res.status(401).json({ success: false, error: 'Token is required' });
            }

            const decoded = jwt.decode(token);
            const clientId = decoded.clientId;
            const clientSecretRecord = await mongoose.connection.collection('app_secrets').findOne({
                clientId,
                recStatus: "active"
            }, { maxTimeMS: maxTimeMS });
            if (!clientSecretRecord) {
                return res.status(401).json({ success: false, error: 'Invalid clientId or clientSecret' });
            }
            try {
                jwt.verify(token, clientSecretRecord.clientSecret); // This will throw an error if verification fails
            } catch (error) {
                return res.status(401).json({ success: false, error: 'Invalid token' });
            } 
            return next();
        } catch (error) {
            console.error('error >> ', error);
            return res.status(500).json({ success: false, error: 'Internal server error' });
        }
    }
}